function(container, apiUrl, tables) {
  let selectedFiles = [];
  let uploadProgress = {};

  // KPI更新関数
  function updateKPIs(uploads) {
    const total = uploads.length;
    const processing = uploads.filter(u => u.翻訳ステータス === '処理中' || u.翻訳ステータス === '待機中').length;
    const thisMonth = uploads.filter(u => u.アップロード日時 && u.アップロード日時.startsWith(new Date().toISOString().slice(0, 7))).length;
    const completed = uploads.filter(u => u.翻訳ステータス === '完了').length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    container.querySelector('#kpi-total-uploads').textContent = total;
    container.querySelector('#kpi-processing').textContent = processing;
    container.querySelector('#kpi-monthly').textContent = thisMonth;
    container.querySelector('#kpi-completion-rate').textContent = completionRate + '%';
  }

  // グラフ初期化
  function initCharts(uploads) {
    // 月別アップロード数グラフ
    const monthlyData = uploads.reduce((acc, upload) => {
      if (upload.アップロード日時) {
        const month = upload.アップロード日時.slice(0, 7);
        acc[month] = (acc[month] || 0) + 1;
      }
      return acc;
    }, {});

    const monthlyChart = new Chart(container.querySelector('#monthly-chart'), {
      type: 'bar',
      data: {
        labels: Object.keys(monthlyData).sort(),
        datasets: [{
          label: 'アップロード数',
          data: Object.values(monthlyData),
          backgroundColor: '#4f46e5',
          borderColor: '#4338ca',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              stepSize: 1
            }
          }
        }
      }
    });

    // ステータス分布グラフ
    const statusData = uploads.reduce((acc, upload) => {
      const status = upload.翻訳ステータス || '未設定';
      acc[status] = (acc[status] || 0) + 1;
      return acc;
    }, {});

    const statusChart = new Chart(container.querySelector('#status-chart'), {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusData),
        datasets: [{
          data: Object.values(statusData),
          backgroundColor: ['#10b981', '#f59e0b', '#ef4444', '#6b7280', '#8b5cf6']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // ファイル一覧描画
  function renderFileList() {
    const tbody = container.querySelector('#file-list');
    tbody.innerHTML = selectedFiles.map((file, index) => {
      const progress = uploadProgress[index] || 0;
      const progressBar = progress > 0 ? 
        `<div style="width: 100%; background: var(--border); border-radius: 4px; height: 8px;">
          <div style="width: ${progress}%; background: #10b981; height: 100%; border-radius: 4px;"></div>
        </div>` : 
        '<span style="color: var(--text-muted);">待機中</span>';

      return `
        <tr data-index="${index}">
          <td style="color: var(--text);">${file.name}</td>
          <td style="color: var(--text);">${file.name.split('.').pop().toUpperCase()}</td>
          <td style="color: var(--text);">${(file.size / 1024 / 1024).toFixed(2)} MB</td>
          <td style="color: var(--text);">
            ${container.querySelector('#source-lang').options[container.querySelector('#source-lang').selectedIndex].text} → 
            ${container.querySelector('#target-lang').options[container.querySelector('#target-lang').selectedIndex].text}
          </td>
          <td>${progressBar}</td>
          <td>
            <button class="action-btn secondary remove-file-btn" data-index="${index}">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // ファイル選択処理
  function handleFiles(files) {
    Array.from(files).forEach(file => {
      if (file.size > 50 * 1024 * 1024) { // 50MB制限
        alert(`ファイル "${file.name}" は50MBを超えています。`);
        return;
      }
      selectedFiles.push(file);
    });
    renderFileList();
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(uploads => {
    updateKPIs(uploads || []);
    initCharts(uploads || []);
  });

  // ドラッグ&ドロップ設定
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');

  dropZone.addEventListener('click', () => fileInput.click());
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = '#4f46e5';
    dropZone.style.backgroundColor = '#f8fafc';
  });
  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'var(--border)';
    dropZone.style.backgroundColor = 'var(--bg-card)';
  });
  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--border)';
    dropZone.style.backgroundColor = 'var(--bg-card)';
    handleFiles(e.dataTransfer.files);
  });

  fileInput.addEventListener('change', (e) => {
    handleFiles(e.target.files);
  });

  // 優先度スライダー
  const prioritySlider = container.querySelector('#priority-slider');
  const priorityValue = container.querySelector('#priority-value');
  prioritySlider.addEventListener('input', (e) => {
    priorityValue.textContent = e.target.value;
  });

  // アップロード実行
  container.querySelector('#btn-upload').addEventListener('click', async () => {
    if (selectedFiles.length === 0) {
      alert('アップロードするファイルを選択してください。');
      return;
    }

    const sourceLang = container.querySelector('#source-lang').value;
    const targetLang = container.querySelector('#target-lang').value;
    const engine = container.querySelector('input[name="engine"]:checked').value;
    const quality = container.querySelector('#quality-level').value;
    const priority = container.querySelector('#priority-slider').value;

    for (let i = 0; i < selectedFiles.length; i++) {
      const file = selectedFiles[i];

      // 進捗シミュレーション
      for (let progress = 0; progress <= 100; progress += 20) {
        uploadProgress[i] = progress;
        renderFileList();
        await new Promise(resolve => setTimeout(resolve, 200));
      }

      // ファイル情報を保存
      const fileData = {
        ユーザーID: 'current-user-id',
        ファイル名: file.name,
        ファイルパス: `/uploads/${Date.now()}_${file.name}`,
        翻訳ステータス: '待機中',
        アップロード日時: new Date().toISOString()
      };

      await window.aivicApi.save(1, fileData);
    }

    alert('アップロードが完了しました。');
    selectedFiles = [];
    uploadProgress = {};
    renderFileList();

    // KPI更新
    window.aivicApi.list(1).then(uploads => {
      updateKPIs(uploads || []);
      initCharts(uploads || []);
    });
  });

  // 全てクリア
  container.querySelector('#btn-clear-all').addEventListener('click', () => {
    if (selectedFiles.length > 0 && confirm('選択中のファイルを全て削除しますか？')) {
      selectedFiles = [];
      uploadProgress = {};
      renderFileList();
    }
  });

  // ファイル削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-file-btn');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      selectedFiles.splice(index, 1);
      delete uploadProgress[index];
      renderFileList();
    }
  });

  // 画面遷移
  container.querySelector('#btn-translation-settings').addEventListener('click', () => {
    window.showScreen("scr-1778473867681");
  });

  container.querySelector('#btn-progress-list').addEventListener('click', () => {
    window.showScreen("scr-1778473170129");
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#progress-table-body");

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const fileData = tables[1].records?.find(f => f.id === r.ファイルID) || {};
      const userData = tables[0].records?.find(u => u.id === r.翻訳者ID) || {};
      const engineData = tables[4].records?.find(e => e.id === fileData.翻訳エンジンID) || {};

      const fileName = fileData.ファイル名 || "不明なファイル";
      const fileSize = formatFileSize(fileData.ファイルサイズ || 0);
      const engineName = engineData.エンジン名 || "未設定";
      const translatorName = userData.ユーザー名 || "未割当";

      const progressPercent = r.進捗率 || 0;
      const status = r.翻訳ステータス || "未着手";

      const startDate = r.翻訳開始日時 ? formatDateTime(r.翻訳開始日時) : "-";
      const estimatedEnd = calculateEstimatedEnd(r.翻訳開始日時, progressPercent);

      // 言語ペアを推定（実際のシステムでは別テーブルで管理）
      const languagePair = guessLanguagePair(fileName);

      return `
        <tr class="row-clickable" data-id="${r.id}">
          <td>${fileName}</td>
          <td>${languagePair.source}</td>
          <td>${languagePair.target}</td>
          <td><span class="status-badge status-${status}">${status}</span></td>
          <td>
            <div class="progress-bar">
              <div class="progress-fill" style="width: ${progressPercent}%"></div>
              <div class="progress-text">${progressPercent}%</div>
            </div>
          </td>
          <td class="datetime-text">${startDate}</td>
          <td class="datetime-text">${estimatedEnd}</td>
          <td><span class="engine-name">${engineName}</span></td>
          <td class="file-size">${fileSize}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細表示</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // ヘルパー関数
  function formatFileSize(bytes) {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return "-";
    const date = new Date(dateStr);
    return date.toLocaleString("ja-JP", {
      year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit"
    });
  }

  function calculateEstimatedEnd(startDate, progress) {
    if (!startDate || progress === 0) return "-";
    const start = new Date(startDate);
    const now = new Date();
    const elapsed = now - start;
    const totalEstimated = (elapsed / progress) * 100;
    const endDate = new Date(start.getTime() + totalEstimated);
    return formatDateTime(endDate);
  }

  function guessLanguagePair(fileName) {
    // ファイル名から言語ペアを推定（実際のシステムでは設定テーブルから取得）
    if (fileName.includes("_en") || fileName.includes("_EN")) {
      return { source: "日本語", target: "英語" };
    } else if (fileName.includes("_zh") || fileName.includes("_CN")) {
      return { source: "日本語", target: "中国語" };
    } else if (fileName.includes("_ko") || fileName.includes("_KR")) {
      return { source: "日本語", target: "韓国語" };
    }
    return { source: "日本語", target: "英語" };
  }

  // 2. 初期データを即座に描画
  renderRows(tables[2].records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const statusFilter = container.querySelector("#filter-status").value;
    const languageFilter = container.querySelector("#filter-language").value;

    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const filtered = rows.filter(r => {
      const fileData = tables[1].records?.find(f => f.id === r.ファイルID) || {};
      const fileName = (fileData.ファイル名 || "").toLowerCase();
      const status = r.翻訳ステータス || "";
      const languagePair = guessLanguagePair(fileData.ファイル名 || "");
      const langCode = `${languagePair.source === "日本語" ? "ja" : "en"}-${languagePair.target === "英語" ? "en" : languagePair.target === "中国語" ? "zh" : "ko"}`;

      const matchKeyword = !keyword || fileName.includes(keyword);
      const matchStatus = !statusFilter || status === statusFilter;
      const matchLanguage = !languageFilter || langCode === languageFilter;

      return matchKeyword && matchStatus && matchLanguage;
    });

    renderRows(filtered);
  });

  // 4. CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const headers = ["ファイル名", "翻訳元言語", "翻訳先言語", "ステータス", "進捗率", "開始日時", "完了予定日時", "翻訳エンジン", "ファイルサイズ"];
    const csvData = [headers.join(",")];

    rows.forEach(r => {
      const fileData = tables[1].records?.find(f => f.id === r.ファイルID) || {};
      const engineData = tables[4].records?.find(e => e.id === fileData.翻訳エンジンID) || {};
      const languagePair = guessLanguagePair(fileData.ファイル名 || "");

      const row = [
        `"${fileData.ファイル名 || ""}"`,
        `"${languagePair.source}"`,
        `"${languagePair.target}"`,
        `"${r.翻訳ステータス || ""}"`,
        `"${r.進捗率 || 0}%"`,
        `"${formatDateTime(r.翻訳開始日時)}"`,
        `"${calculateEstimatedEnd(r.翻訳開始日時, r.進捗率)}"`,
        `"${engineData.エンジン名 || ""}"`,
        `"${formatFileSize(fileData.ファイルサイズ || 0)}"`
      ];
      csvData.push(row.join(","));
    });

    const blob = new Blob(["\uFEFF" + csvData.join("\n")], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "translation_progress.csv";
    link.click();
  });

  // 5. 履歴一覧ボタン
  container.querySelector("#btn-history").addEventListener("click", () => {
    window.showScreen("scr-1778473209133");
  });

  // 6. イベントデリゲーション（行クリック・詳細ボタン）
  container.addEventListener("click", async (e) => {
    // 詳細表示ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      e.stopPropagation();
      window.showScreen("scr-1778473182050");
      return;
    }

    // 行クリック
    const row = e.target.closest(".row-clickable");
    if (row && !e.target.closest("button")) {
      window.showScreen("scr-1778473182050");
      return;
    }
  });

  // 翻訳完了の自動通知チェック（定期実行）
  setInterval(async () => {
    const rows = await window.aivicApi.list(2);
    if (!rows) return;

    const completed = rows.filter(r => r.翻訳ステータス === "完了" && r.進捗率 === 100);
    if (completed.length > 0) {
      // 完了通知画面への自動遷移（実際のシステムでは通知のみ）
      // window.showScreen("scr-1778473915935");
    }
  }, 30000); // 30秒ごとにチェック
}

function(container, apiUrl, tables) {
  // URLパラメータから翻訳進捗IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  const progressId = urlParams.get('id') || (tables[2]?.records?.[0]?.翻訳進捗ID);

  // 進捗詳細データを表示する関数
  function renderProgressDetail(progressData, fileData, engineData) {
    if (!progressData) return;

    // 基本情報の表示
    container.querySelector('#job-id').textContent = progressData.翻訳進捗ID || '-';
    container.querySelector('#file-name').textContent = fileData?.ファイル名 || '-';
    container.querySelector('#source-lang').textContent = '日本語'; // 固定値またはデータから取得
    container.querySelector('#target-lang').textContent = '英語'; // 固定値またはデータから取得
    container.querySelector('#engine-name').textContent = engineData?.エンジン名 || '-';

    // ステータス表示
    const statusBadge = container.querySelector('#status-badge');
    const status = progressData.翻訳ステータス || '未着手';
    statusBadge.textContent = status;
    statusBadge.className = 'status-badge';

    switch(status) {
      case '未着手':
      case '待機中':
        statusBadge.classList.add('status-waiting');
        break;
      case '翻訳中':
      case '処理中':
      case '校正中':
        statusBadge.classList.add('status-processing');
        break;
      case '完了':
      case '翻訳完了':
        statusBadge.classList.add('status-completed');
        break;
      case 'エラー':
      case '差し戻し':
        statusBadge.classList.add('status-error');
        break;
      default:
        statusBadge.classList.add('status-waiting');
    }

    // 進捗率の表示
    const progressRate = progressData.進捗率 || 0;
    container.querySelector('#progress-fill').style.width = `${progressRate}%`;
    container.querySelector('#progress-text').textContent = `${progressRate}%`;

    // 文字数情報（サンプル計算）
    const totalChars = 10000; // 実際はファイルから計算
    const processedChars = Math.floor(totalChars * progressRate / 100);
    container.querySelector('#processed-chars').textContent = processedChars.toLocaleString();
    container.querySelector('#total-chars').textContent = totalChars.toLocaleString();

    // 日時情報
    if (progressData.翻訳開始日時) {
      const startTime = new Date(progressData.翻訳開始日時);
      container.querySelector('#start-time').textContent = startTime.toLocaleString();

      // 実行時間計算
      const now = new Date();
      const executionMs = now - startTime;
      const executionMinutes = Math.floor(executionMs / 60000);
      container.querySelector('#execution-time').textContent = `${executionMinutes}分`;

      // 完了予定時刻計算（進捗率から推定）
      if (progressRate > 0 && progressRate < 100) {
        const estimatedTotalMs = executionMs * 100 / progressRate;
        const estimatedCompletion = new Date(startTime.getTime() + estimatedTotalMs);
        container.querySelector('#estimated-completion').textContent = estimatedCompletion.toLocaleString();
      } else {
        container.querySelector('#estimated-completion').textContent = '-';
      }
    }

    // エラー情報の表示
    if (status === 'エラー' || status === '差し戻し') {
      container.querySelector('#error-section').style.display = 'block';
      container.querySelector('#error-message').textContent = 'エラーが発生しました';
      container.querySelector('#error-details').textContent = '詳細なエラー情報はエラーログをご確認ください。';
    }
  }

  // 初期データの読み込みと表示
  async function loadProgressDetail() {
    try {
      const progressRows = await window.aivicApi.list(2); // 翻訳進捗管理テーブル
      const fileRows = await window.aivicApi.list(1); // ファイルアップロード管理テーブル
      const engineRows = await window.aivicApi.list(4); // 翻訳エンジン設定テーブル

      const progressData = progressRows?.find(row => row.翻訳進捗ID === progressId) || tables[2]?.records?.[0];
      const fileData = fileRows?.find(row => row.ファイルID === progressData?.ファイルID) || tables[1]?.records?.[0];
      const engineData = engineRows?.[0] || tables[4]?.records?.[0];

      renderProgressDetail(progressData, fileData, engineData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // 初期データで表示
      renderProgressDetail(tables[2]?.records?.[0], tables[1]?.records?.[0], tables[4]?.records?.[0]);
    }
  }

  // 画面遷移イベント
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778473170129");
  });

  container.querySelector('#btn-error-log').addEventListener('click', () => {
    window.showScreen("scr-1778473287101");
  });

  // アクションボタンのイベント
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    if (!confirm('翻訳を再実行しますか？')) return;

    try {
      // 進捗をリセットして再実行
      await window.aivicApi.update(2, progressId, {
        翻訳ステータス: '待機中',
        進捗率: 0
      });

      alert('再実行を開始しました。');
      loadProgressDetail(); // 画面を更新
    } catch (error) {
      alert('再実行の開始に失敗しました。');
    }
  });

  container.querySelector('#btn-cancel').addEventListener('click', async () => {
    if (!confirm('翻訳をキャンセルしますか？')) return;

    try {
      await window.aivicApi.update(2, progressId, {
        翻訳ステータス: 'キャンセル'
      });

      alert('翻訳をキャンセルしました。');
      loadProgressDetail(); // 画面を更新
    } catch (error) {
      alert('キャンセル処理に失敗しました。');
    }
  });

  container.querySelector('#btn-download').addEventListener('click', () => {
    const status = container.querySelector('#status-badge').textContent;
    if (status !== '完了' && status !== '翻訳完了') {
      alert('翻訳が完了していないため、ダウンロードできません。');
      return;
    }

    // ダウンロード処理（実際の実装では翻訳結果ファイルをダウンロード）
    alert('翻訳結果をダウンロードします。');
  });

  // 初期データの読み込み
  loadProgressDetail();

  // 定期的な進捗更新（処理中の場合）
  const updateInterval = setInterval(() => {
    const status = container.querySelector('#status-badge').textContent;
    if (status === '処理中' || status === '翻訳中') {
      loadProgressDetail();
    } else {
      clearInterval(updateInterval);
    }
  }, 5000); // 5秒ごとに更新
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#history-tbody');
  const resultCount = container.querySelector('#result-count');
  const selectAll = container.querySelector('#select-all');

  // 翻訳履歴テーブルのインデックスを取得
  const historyTableIndex = tables.findIndex(t => t.tableName === '翻訳履歴テーブル');
  const fileTableIndex = tables.findIndex(t => t.tableName === 'ファイルアップロード管理テーブル');
  const engineTableIndex = tables.findIndex(t => t.tableName === '翻訳エンジン設定テーブル');
  const formatTableIndex = tables.findIndex(t => t.tableName === 'ファイル形式定義テーブル');

  let allHistories = [];
  let allFiles = [];
  let allEngines = [];
  let allFormats = [];

  // ステータスバッジのクラス取得
  function getStatusClass(status) {
    const statusMap = {
      '待機中': 'status-waiting',
      '処理中': 'status-processing', 
      '完了': 'status-completed',
      'エラー': 'status-error',
      'キャンセル': 'status-cancelled'
    };
    return statusMap[status] || 'status-waiting';
  }

  // 品質スコア表示
  function renderQualityScore(score) {
    if (!score) return '<span class="muted">-</span>';
    return `
      <div class="quality-score">
        <span>${score}</span>
        <div class="score-bar">
          <div class="score-fill" style="width: ${score}%"></div>
        </div>
      </div>
    `;
  }

  // テーブル再描画関数
  function renderRows(histories) {
    if (!histories || histories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="muted" style="text-align: center; padding: 40px;">履歴データがありません</td></tr>';
      resultCount.textContent = '0件の履歴';
      return;
    }

    tbody.innerHTML = histories.map(history => {
      const file = allFiles.find(f => f.id === history.ファイルアップロードID) || {};
      const engine = allEngines.find(e => e.id === history.翻訳エンジンID) || {};

      return `
        <tr data-id="${history.id}" class="history-row">
          <td><input type="checkbox" class="row-checkbox" data-id="${history.id}"></td>
          <td>${file.ファイル名 || '-'}</td>
          <td>${engine.エンジン名 || '-'}</td>
          <td><span class="status-badge ${getStatusClass(history.翻訳ステータス)}">${history.翻訳ステータス || '-'}</span></td>
          <td>${renderQualityScore(history.翻訳品質スコア)}</td>
          <td>${history.翻訳開始日時 ? new Date(history.翻訳開始日時).toLocaleString() : '-'}</td>
          <td>
            <div class="action-buttons">
              <button class="action-btn secondary detail-btn" data-id="${history.id}">履歴詳細</button>
              <button class="action-btn secondary delete-btn" data-id="${history.id}">削除</button>
            </div>
          </td>
        </tr>
      `;
    }).join('');

    resultCount.textContent = `${histories.length}件の履歴`;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [histories, files, engines, formats] = await Promise.all([
        window.aivicApi.list(historyTableIndex),
        window.aivicApi.list(fileTableIndex), 
        window.aivicApi.list(engineTableIndex),
        window.aivicApi.list(formatTableIndex)
      ]);

      allHistories = histories || tables[historyTableIndex]?.records || [];
      allFiles = files || tables[fileTableIndex]?.records || [];
      allEngines = engines || tables[engineTableIndex]?.records || [];
      allFormats = formats || tables[formatTableIndex]?.records || [];

      // セレクトボックスの初期化
      const engineSelect = container.querySelector('#select-engine');
      const formatSelect = container.querySelector('#select-format');

      engineSelect.innerHTML = '<option value="">全て</option>' + 
        allEngines.map(e => `<option value="${e.id}">${e.エンジン名}</option>`).join('');

      formatSelect.innerHTML = '<option value="">全て</option>' + 
        allFormats.map(f => `<option value="${f.id}">${f.形式名}</option>`).join('');

      renderRows(allHistories);
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      renderRows(tables[historyTableIndex]?.records || []);
    }
  }

  // 検索・フィルタリング
  function performSearch() {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const dateFrom = container.querySelector('#input-date-from').value;
    const dateTo = container.querySelector('#input-date-to').value;
    const status = container.querySelector('#select-status').value;
    const engineId = container.querySelector('#select-engine').value;
    const formatId = container.querySelector('#select-format').value;

    let filtered = allHistories.filter(history => {
      // キーワード検索
      if (keyword) {
        const file = allFiles.find(f => f.id === history.ファイルアップロードID) || {};
        const engine = allEngines.find(e => e.id === history.翻訳エンジンID) || {};
        const searchText = `${file.ファイル名 || ''} ${engine.エンジン名 || ''}`.toLowerCase();
        if (!searchText.includes(keyword)) return false;
      }

      // 日付範囲
      if (dateFrom || dateTo) {
        const historyDate = history.翻訳開始日時 ? new Date(history.翻訳開始日時).toISOString().split('T')[0] : '';
        if (dateFrom && historyDate < dateFrom) return false;
        if (dateTo && historyDate > dateTo) return false;
      }

      // ステータス
      if (status && history.翻訳ステータス !== status) return false;

      // 翻訳エンジン
      if (engineId && history.翻訳エンジンID !== engineId) return false;

      // ファイル形式（ファイル経由で判定）
      if (formatId) {
        const file = allFiles.find(f => f.id === history.ファイルアップロードID);
        if (!file) return false;
        // ファイル形式の判定ロジックは簡略化
      }

      return true;
    });

    renderRows(filtered);
  }

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  // 条件クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#input-search').value = '';
    container.querySelector('#input-date-from').value = '';
    container.querySelector('#input-date-to').value = '';
    container.querySelector('#select-status').value = '';
    container.querySelector('#select-engine').value = '';
    container.querySelector('#select-format').value = '';
    renderRows(allHistories);
  });

  // 新規翻訳ボタン
  container.querySelector('#btn-new-translation').addEventListener('click', () => {
    // 翻訳アップロード画面などに遷移
    alert('新規翻訳画面への遷移機能は別途実装が必要です');
  });

  // CSVエクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const histories = await window.aivicApi.list(historyTableIndex);
      if (!histories || histories.length === 0) {
        alert('エクスポートするデータがありません');
        return;
      }

      const headers = ['翻訳履歴ID', 'ファイル名', '翻訳エンジン', '翻訳ステータス', '翻訳品質スコア', '翻訳開始日時'];
      const csvRows = [headers.join(',')];

      histories.forEach(history => {
        const file = allFiles.find(f => f.id === history.ファイルアップロードID) || {};
        const engine = allEngines.find(e => e.id === history.翻訳エンジンID) || {};

        const row = [
          history.id || '',
          `"${(file.ファイル名 || '').replace(/"/g, '""')}"`,
          `"${(engine.エンジン名 || '').replace(/"/g, '""')}"`,
          history.翻訳ステータス || '',
          history.翻訳品質スコア || '',
          history.翻訳開始日時 || ''
        ];
        csvRows.push(row.join(','));
      });

      const csvContent = '\uFEFF' + csvRows.join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `翻訳履歴_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      alert('CSVエクスポートに失敗しました');
    }
  });

  // 全選択チェックボックス
  selectAll.addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括削除ボタン
  container.querySelector('#btn-bulk-delete').addEventListener('click', async () => {
    const checkedBoxes = container.querySelectorAll('.row-checkbox:checked');
    if (checkedBoxes.length === 0) {
      alert('削除する履歴を選択してください');
      return;
    }

    if (!confirm(`選択した${checkedBoxes.length}件の履歴を削除しますか？`)) return;

    try {
      const deletePromises = Array.from(checkedBoxes).map(cb => 
        window.aivicApi.delete(historyTableIndex, cb.dataset.id)
      );

      await Promise.all(deletePromises);
      await loadInitialData();
      selectAll.checked = false;
      alert('選択した履歴を削除しました');
    } catch (error) {
      console.error('一括削除エラー:', error);
      alert('一括削除に失敗しました');
    }
  });

  // イベントデリゲーション（行クリック、削除、詳細）
  container.addEventListener('click', async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この翻訳履歴を削除しますか？')) return;

      try {
        await window.aivicApi.delete(historyTableIndex, deleteBtn.dataset.id);
        await loadInitialData();
        alert('翻訳履歴を削除しました');
      } catch (error) {
        console.error('削除エラー:', error);
        alert('削除に失敗しました');
      }
      return;
    }

    // 履歴詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen("scr-1778473247810");
      return;
    }

    // 行クリック（詳細画面へ）
    const row = e.target.closest('.history-row');
    if (row && !e.target.closest('button') && !e.target.closest('input')) {
      window.showScreen("scr-1778473247810");
      return;
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

function(container, apiUrl, tables) {
  // URLパラメータから翻訳履歴IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  const historyId = urlParams.get('id') || (tables[5]?.records?.[0]?.翻訳履歴ID);

  // 詳細データを表示する関数
  async function loadTranslationDetail(id) {
    try {
      // 翻訳履歴データを取得
      const historyRows = await window.aivicApi.list(5); // 翻訳履歴テーブル
      const history = historyRows?.find(r => r.翻訳履歴ID === id);

      if (!history) {
        container.querySelector('#translation-history-id').textContent = 'データが見つかりません';
        return;
      }

      // 関連データを取得
      const fileRows = await window.aivicApi.list(1); // ファイルアップロード管理テーブル
      const userRows = await window.aivicApi.list(0); // ユーザー管理テーブル
      const engineRows = await window.aivicApi.list(4); // 翻訳エンジン設定テーブル
      const progressRows = await window.aivicApi.list(2); // 翻訳進捗管理テーブル
      const evaluationRows = await window.aivicApi.list(7); // 翻訳品質評価テーブル
      const errorRows = await window.aivicApi.list(6); // エラーログテーブル

      // 関連データを取得
      const fileData = fileRows?.find(f => f.ファイルID === history.ファイルアップロードID);
      const translatorData = userRows?.find(u => u.ユーザーID === fileData?.ユーザーID);
      const engineData = engineRows?.find(e => e.エンジンID === history.翻訳エンジンID);
      const progressData = progressRows?.find(p => p.ファイルID === history.ファイルアップロードID);
      const evaluationData = evaluationRows?.find(e => e.翻訳履歴ID === history.翻訳履歴ID);
      const errorData = errorRows?.find(e => e.ユーザーID === fileData?.ユーザーID && e.発生日時 >= history.翻訳開始日時);

      // 基本情報を表示
      container.querySelector('#translation-history-id').textContent = history.翻訳履歴ID || '-';
      container.querySelector('#translation-start-datetime').textContent = 
        history.翻訳開始日時 ? new Date(history.翻訳開始日時).toLocaleString('ja-JP') : '-';
      container.querySelector('#translator-name').textContent = translatorData?.ユーザー名 || '-';

      // ステータス表示
      const statusElement = container.querySelector('#translation-status');
      const status = history.翻訳ステータス || 'unknown';
      statusElement.textContent = status;
      statusElement.className = 'status-badge';

      if (status === '完了') {
        statusElement.classList.add('completed');
      } else if (status === '処理中') {
        statusElement.classList.add('processing');
      } else if (status === 'エラー') {
        statusElement.classList.add('error');
      } else {
        statusElement.classList.add('waiting');
      }

      // 進捗率表示
      const progressRate = progressData?.進捗率 || 0;
      container.querySelector('#progress-fill').style.width = `${progressRate}%`;
      container.querySelector('#progress-text').textContent = `${progressRate}%`;

      // ファイル情報
      container.querySelector('#original-filename').textContent = fileData?.ファイル名 || '-';
      container.querySelector('#translated-filename').textContent = 
        fileData?.ファイル名 ? `translated_${fileData.ファイル名}` : '-';

      // 翻訳設定（サンプルデータ）
      container.querySelector('#source-language').textContent = '日本語';
      container.querySelector('#target-language').textContent = '英語';
      container.querySelector('#translation-engine').textContent = engineData?.エンジン名 || '-';

      // 品質評価
      container.querySelector('#quality-score').textContent = 
        history.翻訳品質スコア ? `${history.翻訳品質スコア}/100` : '-';

      const commentsArea = container.querySelector('#evaluation-comments');
      if (evaluationData?.評価コメント) {
        commentsArea.textContent = evaluationData.評価コメント;
        commentsArea.style.fontStyle = 'normal';
      } else {
        commentsArea.textContent = '評価コメントはありません';
        commentsArea.style.fontStyle = 'italic';
      }

      // エラー情報
      const errorSection = container.querySelector('#error-section');
      if (errorData && status === 'エラー') {
        errorSection.classList.remove('hidden');
        container.querySelector('#error-level').textContent = errorData.エラーレベル || '-';
        container.querySelector('#error-message').textContent = errorData.エラーメッセージ || '-';
        container.querySelector('#error-datetime').textContent = 
          errorData.発生日時 ? new Date(errorData.発生日時).toLocaleString('ja-JP') : '-';
      } else {
        errorSection.classList.add('hidden');
      }

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      container.querySelector('#translation-history-id').textContent = 'データ読み込みエラー';
    }
  }

  // 初期データ読み込み
  if (historyId) {
    loadTranslationDetail(historyId);
  } else {
    // サンプルデータを表示
    const sampleHistory = tables[5]?.records?.[0];
    if (sampleHistory) {
      loadTranslationDetail(sampleHistory.翻訳履歴ID);
    }
  }

  // 再ダウンロードボタン
  container.querySelector('#btn-redownload').addEventListener('click', () => {
    window.showScreen("scr-1778473937024");
  });

  // 品質評価ボタン
  container.querySelector('#btn-quality-evaluation').addEventListener('click', () => {
    window.showScreen("scr-1778473262058");
  });

  // ファイルダウンロードボタン
  container.querySelector('#btn-download-original').addEventListener('click', () => {
    // 元ファイルダウンロード処理
    const filename = container.querySelector('#original-filename').textContent;
    if (filename && filename !== '-') {
      // 実際の実装では、ファイルパスを使用してダウンロード処理を行う
      alert(`${filename} をダウンロードします`);
    }
  });

  container.querySelector('#btn-download-translated').addEventListener('click', () => {
    // 翻訳後ファイルダウンロード処理
    const filename = container.querySelector('#translated-filename').textContent;
    if (filename && filename !== '-') {
      // 実際の実装では、翻訳後ファイルパスを使用してダウンロード処理を行う
      alert(`${filename} をダウンロードします`);
    }
  });
}

function(container, apiUrl, tables) {
  const historyTbody = container.querySelector("#history-tbody");
  const evaluationTbody = container.querySelector("#evaluation-tbody");
  const selectTranslation = container.querySelector("#select-translation");
  const originalText = container.querySelector("#original-text");
  const translatedText = container.querySelector("#translated-text");

  let translationHistories = [];
  let evaluations = [];

  // 翻訳履歴再描画関数
  function renderHistoryRows(rows) {
    historyTbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td style="color: var(--text);">${r.ファイル名 || "不明"}</td>
        <td style="color: var(--text);">${r.エンジン名 || "不明"}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; 
                       background: ${r.翻訳ステータス === '完了' ? '#1a4a2e' : '#2a3a4a'}; 
                       color: #d0e4ff;">
            ${r.翻訳ステータス || "不明"}
          </span>
        </td>
        <td>
          <button class="action-btn secondary select-btn" data-id="${r.id}">選択</button>
        </td>
      </tr>
    `).join("");

    // セレクトボックスも更新
    selectTranslation.innerHTML = '<option value="">選択してください</option>' + 
      rows.map(r => `<option value="${r.id}">${r.ファイル名 || "不明"} - ${r.エンジン名 || "不明"}</option>`).join("");
  }

  // 評価履歴再描画関数
  function renderEvaluationRows(rows) {
    evaluationTbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td style="color: var(--text);">${r.評価日時 ? new Date(r.評価日時).toLocaleString() : ""}</td>
        <td style="color: var(--text);">${r.翻訳履歴ID || ""}</td>
        <td style="color: var(--text);">${r.評価者名 || ""}</td>
        <td style="color: var(--text);">${r.品質スコア || ""}</td>
        <td style="color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis;">${r.評価コメント || ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ読み込み
  async function loadData() {
    const historyRows = await window.aivicApi.list(5); // 翻訳履歴テーブル
    const evaluationRows = await window.aivicApi.list(8); // 翻訳品質評価テーブル

    if (historyRows) {
      translationHistories = historyRows;
      renderHistoryRows(historyRows);
    }

    if (evaluationRows) {
      evaluations = evaluationRows;
      renderEvaluationRows(evaluationRows);
    }
  }

  loadData();

  // 検索機能
  container.querySelector("#input-search").addEventListener("input", (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = translationHistories.filter(r => 
      JSON.stringify(r).toLowerCase().includes(keyword)
    );
    renderHistoryRows(filtered);
  });

  // 翻訳選択
  container.addEventListener("click", async (e) => {
    const selectBtn = e.target.closest(".select-btn");
    if (selectBtn) {
      const historyId = selectBtn.dataset.id;
      selectTranslation.value = historyId;

      // 翻訳内容を表示（サンプルデータ）
      const history = translationHistories.find(h => h.id === historyId);
      if (history) {
        originalText.textContent = "これは原文のサンプルテキストです。実際の翻訳システムでは、選択された翻訳履歴に対応する原文が表示されます。";
        translatedText.textContent = "This is a sample text of the translation. In the actual translation system, the translated text corresponding to the selected translation history will be displayed.";
      }
    }
  });

  // セレクトボックス変更
  selectTranslation.addEventListener("change", (e) => {
    const historyId = e.target.value;
    if (historyId) {
      const history = translationHistories.find(h => h.id === historyId);
      if (history) {
        originalText.textContent = "これは原文のサンプルテキストです。実際の翻訳システムでは、選択された翻訳履歴に対応する原文が表示されます。";
        translatedText.textContent = "This is a sample text of the translation. In the actual translation system, the translated text corresponding to the selected translation history will be displayed.";
      }
    } else {
      originalText.textContent = "評価対象を選択してください";
      translatedText.textContent = "評価対象を選択してください";
    }
  });

  // 評価保存
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const translationHistoryId = selectTranslation.value;
    const score = container.querySelector("#input-score").value;
    const comment = container.querySelector("#input-comment").value;

    const accuracy = container.querySelector('input[name="accuracy"]:checked')?.value;
    const naturalness = container.querySelector('input[name="naturalness"]:checked')?.value;
    const terminology = container.querySelector('input[name="terminology"]:checked')?.value;
    const grammar = container.querySelector('input[name="grammar"]:checked')?.value;

    if (!translationHistoryId) {
      alert("評価対象の翻訳を選択してください");
      return;
    }

    if (!score || score < 1 || score > 100) {
      alert("品質スコア（1-100）を入力してください");
      return;
    }

    const evaluationData = {
      翻訳履歴ID: translationHistoryId,
      評価者ID: "current-user-id", // 実際のシステムでは現在のユーザーIDを使用
      品質スコア: parseInt(score),
      評価コメント: comment,
      評価日時: new Date().toISOString(),
      翻訳精度評価: accuracy ? parseInt(accuracy) : null,
      自然さ評価: naturalness ? parseInt(naturalness) : null,
      専門用語適切性評価: terminology ? parseInt(terminology) : null,
      文法正確性評価: grammar ? parseInt(grammar) : null
    };

    const saved = await window.aivicApi.save(8, evaluationData);
    if (saved) {
      alert("評価を保存しました");
      loadData(); // 再読み込み

      // フォームクリア
      container.querySelector("#btn-clear").click();
    }
  });

  // フォームクリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-score").value = "";
    container.querySelector("#input-comment").value = "";
    container.querySelectorAll('input[type="radio"]').forEach(radio => radio.checked = false);
    selectTranslation.value = "";
    originalText.textContent = "評価対象を選択してください";
    translatedText.textContent = "評価対象を選択してください";
  });

  // 評価履歴の編集・削除
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この評価を削除しますか？")) return;
      await window.aivicApi.delete(8, deleteBtn.dataset.id);
      loadData();
    }

    if (editBtn) {
      const evaluation = evaluations.find(ev => ev.id === editBtn.dataset.id);
      if (evaluation) {
        // 編集フォームに値を設定
        selectTranslation.value = evaluation.翻訳履歴ID || "";
        container.querySelector("#input-score").value = evaluation.品質スコア || "";
        container.querySelector("#input-comment").value = evaluation.評価コメント || "";

        // ラジオボタンの選択状態を復元
        if (evaluation.翻訳精度評価) {
          const accuracyRadio = container.querySelector(`input[name="accuracy"][value="${evaluation.翻訳精度評価}"]`);
          if (accuracyRadio) accuracyRadio.checked = true;
        }

        // 翻訳内容表示を更新
        selectTranslation.dispatchEvent(new Event('change'));
      }
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(8);
    if (!rows) return;

    const headers = ["評価ID", "翻訳履歴ID", "評価者ID", "品質スコア", "評価コメント", "評価日時"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(row => [
        row.id || "",
        row.翻訳履歴ID || "",
        row.評価者ID || "",
        row.品質スコア || "",
        `"${(row.評価コメント || "").replace(/"/g, '""')}"`,
        row.評価日時 || ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "translation_quality_evaluations.csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#error-log-tbody");
  const modal = container.querySelector("#error-detail-modal");
  const modalContent = container.querySelector("#error-detail-content");

  // ユーザー情報とファイル情報をキャッシュ
  let users = [];
  let files = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      users = await window.aivicApi.list(0) || []; // ユーザー管理テーブル
      files = await window.aivicApi.list(1) || []; // ファイルアップロード管理テーブル
    } catch (error) {
      console.error("初期データ読み込みエラー:", error);
    }
  }

  // ユーザー名取得
  function getUserName(userId) {
    if (!userId) return "-";
    const user = users.find(u => u.id === userId);
    return user ? user.ユーザー名 || user.user_name || "-" : "-";
  }

  // ファイル名取得
  function getFileName(errorMessage) {
    // エラーメッセージからファイル名を推測
    const file = files.find(f => errorMessage && errorMessage.includes(f.ファイル名 || f.file_name || ""));
    return file ? (file.ファイル名 || file.file_name || "-") : "-";
  }

  // エラーレベルバッジ
  function getErrorLevelBadge(level) {
    const colors = {
      ERROR: "background: #dc2626; color: #ffffff;",
      WARNING: "background: #f59e0b; color: #ffffff;",
      INFO: "background: #3b82f6; color: #ffffff;"
    };
    const style = colors[level] || "background: var(--bg-card); color: var(--text);";
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500; ${style}">${level || "-"}</span>`;
  }

  // 解決状態バッジ
  function getResolvedBadge(resolved) {
    if (resolved) {
      return `<span style="padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500; background: #16a34a; color: #ffffff;">解決済み</span>`;
    } else {
      return `<span style="padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500; background: #dc2626; color: #ffffff;">未解決</span>`;
    }
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const errorDate = r.発生日時 || r.error_date || r.created_at || "";
      const errorLevel = r.エラーレベル || r.error_level || "";
      const errorMessage = r.エラーメッセージ || r.error_message || "";
      const userId = r.ユーザーID || r.user_id || "";
      const resolved = r.解決済みフラグ || r.resolved_flag || false;

      return `
        <tr data-id="${r.id}">
          <td>${errorDate ? new Date(errorDate).toLocaleString() : "-"}</td>
          <td>${getErrorLevelBadge(errorLevel)}</td>
          <td style="max-width: 300px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${errorMessage}">${errorMessage || "-"}</td>
          <td>${getUserName(userId)}</td>
          <td>${getFileName(errorMessage)}</td>
          <td>${getResolvedBadge(resolved)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
            ${!resolved ? `<button class="action-btn resolve-btn" data-id="${r.id}">解決済みにする</button>` : ""}
          </td>
        </tr>
      `;
    }).join("");
  }

  // 初期データ表示
  async function initialize() {
    await loadInitialData();
    const errorLogs = await window.aivicApi.list(5) || tables[5]?.records || []; // エラーログテーブル
    renderRows(errorLogs);
  }

  // 検索実行
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const errorLevel = container.querySelector("#filter-error-level").value;
    const dateStart = container.querySelector("#filter-date-start").value;
    const dateEnd = container.querySelector("#filter-date-end").value;
    const userFilter = container.querySelector("#filter-user").value.toLowerCase();
    const fileFilter = container.querySelector("#filter-file").value.toLowerCase();

    const allRows = await window.aivicApi.list(5) || [];

    const filteredRows = allRows.filter(r => {
      const errorLevelMatch = !errorLevel || (r.エラーレベル || r.error_level || "") === errorLevel;

      const errorDate = r.発生日時 || r.error_date || r.created_at || "";
      const dateStartMatch = !dateStart || !errorDate || new Date(errorDate) >= new Date(dateStart);
      const dateEndMatch = !dateEnd || !errorDate || new Date(errorDate) <= new Date(dateEnd);

      const userName = getUserName(r.ユーザーID || r.user_id || "").toLowerCase();
      const userMatch = !userFilter || userName.includes(userFilter);

      const fileName = getFileName(r.エラーメッセージ || r.error_message || "").toLowerCase();
      const fileMatch = !fileFilter || fileName.includes(fileFilter);

      return errorLevelMatch && dateStartMatch && dateEndMatch && userMatch && fileMatch;
    });

    renderRows(filteredRows);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(5) || [];

    const headers = ["発生日時", "エラーレベル", "エラーメッセージ", "発生ユーザー", "翻訳ファイル名", "解決状態"];
    const csvData = [headers.join(",")];

    allRows.forEach(r => {
      const errorDate = r.発生日時 || r.error_date || r.created_at || "";
      const errorLevel = r.エラーレベル || r.error_level || "";
      const errorMessage = (r.エラーメッセージ || r.error_message || "").replace(/"/g, '""');
      const userName = getUserName(r.ユーザーID || r.user_id || "");
      const fileName = getFileName(r.エラーメッセージ || r.error_message || "");
      const resolved = (r.解決済みフラグ || r.resolved_flag) ? "解決済み" : "未解決";

      csvData.push([
        errorDate ? new Date(errorDate).toLocaleString() : "",
        errorLevel,
        `"${errorMessage}"`,
        userName,
        fileName,
        resolved
      ].join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `error_logs_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // エラー詳細表示
  function showErrorDetail(errorId) {
    window.aivicApi.list(5).then(rows => {
      const error = rows.find(r => r.id === errorId);
      if (!error) return;

      const errorDate = error.発生日時 || error.error_date || error.created_at || "";
      const errorLevel = error.エラーレベル || error.error_level || "";
      const errorMessage = error.エラーメッセージ || error.error_message || "";
      const userId = error.ユーザーID || error.user_id || "";
      const resolved = error.解決済みフラグ || error.resolved_flag || false;

      modalContent.innerHTML = `
        <div style="display: grid; gap: 1rem;">
          <div>
            <label style="font-weight: 600; color: var(--text);">発生日時</label>
            <div style="color: var(--text);">${errorDate ? new Date(errorDate).toLocaleString() : "-"}</div>
          </div>
          <div>
            <label style="font-weight: 600; color: var(--text);">エラーレベル</label>
            <div>${getErrorLevelBadge(errorLevel)}</div>
          </div>
          <div>
            <label style="font-weight: 600; color: var(--text);">発生ユーザー</label>
            <div style="color: var(--text);">${getUserName(userId)}</div>
          </div>
          <div>
            <label style="font-weight: 600; color: var(--text);">翻訳ファイル名</label>
            <div style="color: var(--text);">${getFileName(errorMessage)}</div>
          </div>
          <div>
            <label style="font-weight: 600; color: var(--text);">解決状態</label>
            <div>${getResolvedBadge(resolved)}</div>
          </div>
          <div>
            <label style="font-weight: 600; color: var(--text);">エラーメッセージ</label>
            <div style="background: var(--bg-card); padding: 1rem; border-radius: 0.5rem; border: 1px solid var(--border); white-space: pre-wrap; color: var(--text);">${errorMessage || "-"}</div>
          </div>
        </div>
      `;

      modal.classList.remove("hidden");
    });
  }

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    modal.classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showErrorDetail(detailBtn.dataset.id);
      return;
    }

    // 解決済みボタン
    const resolveBtn = e.target.closest(".resolve-btn");
    if (resolveBtn) {
      if (!confirm("このエラーを解決済みにしますか？")) return;

      const updated = await window.aivicApi.update(5, resolveBtn.dataset.id, {
        解決済みフラグ: true,
        resolved_flag: true
      });

      if (updated) {
        const allRows = await window.aivicApi.list(5) || [];
        renderRows(allRows);
      }
      return;
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentTranslationId = null;
  let selectedQualityScore = null;

  // 翻訳履歴テーブル再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.翻訳開始日時 || ""}</td>
        <td>${r.翻訳エンジン名 || ""}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; background: ${getStatusColor(r.翻訳ステータス)}; color: #ffffff; font-size: 12px;">
            ${r.翻訳ステータス || ""}
          </span>
        </td>
        <td>${r.翻訳品質スコア || "-"}</td>
        <td>${calculateProcessingTime(r.翻訳開始日時) || "-"}</td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${r.id}">表示</button>
        </td>
      </tr>
    `).join("");
  }

  // ステータス色取得
  function getStatusColor(status) {
    switch(status) {
      case "完了": return "#28a745";
      case "処理中": return "#007bff";
      case "エラー": return "#dc3545";
      case "待機中": return "#6c757d";
      default: return "#6c757d";
    }
  }

  // 処理時間計算
  function calculateProcessingTime(startTime) {
    if (!startTime) return "-";
    // 実際の実装では終了時間との差分を計算
    return "2分30秒";
  }

  // 翻訳結果詳細表示
  function displayTranslationResult(translationData) {
    if (!translationData) return;

    container.querySelector("#file-name").textContent = translationData.ファイル名 || "-";
    container.querySelector("#translation-status").textContent = translationData.翻訳ステータス || "-";
    container.querySelector("#translation-engine").textContent = translationData.エンジン名 || "-";
    container.querySelector("#processing-time").textContent = calculateProcessingTime(translationData.翻訳開始日時);
    container.querySelector("#accuracy-score").textContent = translationData.翻訳品質スコア ? `${translationData.翻訳品質スコア}/100` : "-";
    container.querySelector("#translator").textContent = translationData.翻訳者名 || "-";

    // 原文・翻訳文表示（実際の実装では別テーブルから取得）
    container.querySelector("#original-text").innerHTML = "これは原文のサンプルテキストです。実際の翻訳システムでは、アップロードされたファイルの内容が表示されます。";
    container.querySelector("#translated-text").innerHTML = "This is a sample text of the original document. In an actual translation system, the content of uploaded files will be displayed.";

    currentTranslationId = translationData.id;
  }

  // 初期データ表示
  const translationHistories = tables.find(t => t.tableName === "翻訳履歴テーブル");
  if (translationHistories && translationHistories.records.length > 0) {
    renderHistoryRows(translationHistories.records);
    // 最新の翻訳結果を表示
    displayTranslationResult(translationHistories.records[0]);
  }

  // 品質評価ボタンイベント
  container.querySelector("#btn-quality-excellent").addEventListener("click", () => {
    selectedQualityScore = 5;
    highlightSelectedQuality(5);
  });

  container.querySelector("#btn-quality-good").addEventListener("click", () => {
    selectedQualityScore = 4;
    highlightSelectedQuality(4);
  });

  container.querySelector("#btn-quality-average").addEventListener("click", () => {
    selectedQualityScore = 3;
    highlightSelectedQuality(3);
  });

  container.querySelector("#btn-quality-poor").addEventListener("click", () => {
    selectedQualityScore = 2;
    highlightSelectedQuality(2);
  });

  container.querySelector("#btn-quality-bad").addEventListener("click", () => {
    selectedQualityScore = 1;
    highlightSelectedQuality(1);
  });

  // 品質評価ボタンのハイライト
  function highlightSelectedQuality(score) {
    const buttons = container.querySelectorAll("[id^='btn-quality-']");
    buttons.forEach(btn => {
      btn.style.background = "";
      btn.style.color = "";
    });

    const selectedBtn = container.querySelector(`#btn-quality-${getScoreLabel(score)}`);
    if (selectedBtn) {
      selectedBtn.style.background = "var(--primary)";
      selectedBtn.style.color = "#ffffff";
    }
  }

  function getScoreLabel(score) {
    switch(score) {
      case 5: return "excellent";
      case 4: return "good";
      case 3: return "average";
      case 2: return "poor";
      case 1: return "bad";
      default: return "average";
    }
  }

  // ダウンロードボタン
  container.querySelector("#btn-download").addEventListener("click", () => {
    window.showScreen("scr-1778473788213");
  });

  // 品質評価ボタン
  container.querySelector("#btn-quality-evaluation").addEventListener("click", () => {
    window.showScreen("scr-1778473262058");
  });

  // 修正指示ボタン
  container.querySelector("#btn-correction-request").addEventListener("click", () => {
    window.showScreen("scr-1778473951849");
  });

  // 再翻訳依頼ボタン
  container.querySelector("#btn-retranslate").addEventListener("click", async () => {
    if (!currentTranslationId) {
      alert("翻訳データが選択されていません。");
      return;
    }

    if (!confirm("再翻訳を依頼しますか？")) return;

    const translationHistoryIndex = tables.findIndex(t => t.tableName === "翻訳履歴テーブル");
    if (translationHistoryIndex !== -1) {
      const updated = await window.aivicApi.update(translationHistoryIndex, currentTranslationId, {
        翻訳ステータス: "待機中"
      });

      if (updated) {
        alert("再翻訳依頼を送信しました。");
        const rows = await window.aivicApi.list(translationHistoryIndex);
        if (rows) renderHistoryRows(rows);
      }
    }
  });

  // 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!currentTranslationId) {
      alert("翻訳データが選択されていません。");
      return;
    }

    if (!confirm("この翻訳結果を承認しますか？")) return;

    const translationHistoryIndex = tables.findIndex(t => t.tableName === "翻訳履歴テーブル");
    if (translationHistoryIndex !== -1) {
      const updated = await window.aivicApi.update(translationHistoryIndex, currentTranslationId, {
        翻訳ステータス: "承認済み"
      });

      if (updated) {
        alert("翻訳結果を承認しました。");
        const rows = await window.aivicApi.list(translationHistoryIndex);
        if (rows) renderHistoryRows(rows);
      }
    }
  });

  // 履歴行クリックイベント
  container.addEventListener("click", async (e) => {
    const viewBtn = e.target.closest(".view-btn");
    if (viewBtn) {
      const translationId = viewBtn.dataset.id;
      const translationHistoryIndex = tables.findIndex(t => t.tableName === "翻訳履歴テーブル");

      if (translationHistoryIndex !== -1) {
        const rows = await window.aivicApi.list(translationHistoryIndex);
        if (rows) {
          const selectedTranslation = rows.find(r => r.id === translationId);
          if (selectedTranslation) {
            displayTranslationResult(selectedTranslation);
          }
        }
      }
    }
  });

  // 初期データ読み込み
  const translationHistoryIndex = tables.findIndex(t => t.tableName === "翻訳履歴テーブル");
  if (translationHistoryIndex !== -1) {
    window.aivicApi.list(translationHistoryIndex).then(rows => {
      if (rows) {
        renderHistoryRows(rows);
        if (rows.length > 0) {
          displayTranslationResult(rows[0]);
        }
      }
    });
  }
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#files-tbody");
  const progressDiv = container.querySelector("#download-progress");
  const progressBar = container.querySelector("#progress-bar");
  const progressText = container.querySelector("#progress-text");
  const previewModal = container.querySelector("#preview-modal");
  const previewContent = container.querySelector("#preview-content");

  // 翻訳履歴テーブルのインデックスを取得
  const translationHistoryIndex = tables.findIndex(t => t.tableName.includes('翻訳履歴'));
  const fileUploadIndex = tables.findIndex(t => t.tableName.includes('ファイルアップロード'));

  // 言語ペアマッピング
  const languagePairs = {
    'ja-en': '日本語→英語',
    'en-ja': '英語→日本語', 
    'ja-zh': '日本語→中国語',
    'zh-ja': '中国語→日本語'
  };

  // ファイルサイズをフォーマット
  function formatFileSize(bytes) {
    if (!bytes) return '-';
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return Math.round(bytes / Math.pow(1024, i) * 100) / 100 + ' ' + sizes[i];
  }

  // 品質スコアの表示
  function formatQualityScore(score) {
    if (!score) return '-';
    let color = '#666';
    if (score >= 80) color = '#28a745';
    else if (score >= 60) color = '#ffc107';
    else color = '#dc3545';
    return `<span style="color: ${color}; font-weight: bold;">${score}点</span>`;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td><input type="checkbox" class="file-checkbox" data-id="${r.id}"></td>
        <td>${r.ファイル名 || r.fileName || '-'}</td>
        <td>${languagePairs[r.翻訳言語ペア] || r.翻訳言語ペア || 'ja-en'}</td>
        <td>${r.翻訳完了日時 ? new Date(r.翻訳完了日時).toLocaleString() : '-'}</td>
        <td>${formatFileSize(r.ファイルサイズ || Math.floor(Math.random() * 5000000) + 100000)}</td>
        <td>${formatQualityScore(r.翻訳品質スコア || Math.floor(Math.random() * 40) + 60)}</td>
        <td>
          <button class="action-btn secondary preview-btn" data-id="${r.id}" style="margin-right: 8px;">プレビュー</button>
          <button class="action-btn download-btn" data-id="${r.id}" style="margin-right: 8px;">ダウンロード</button>
          <button class="action-btn secondary history-btn" data-id="${r.id}">履歴</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示（翻訳完了のもののみ）
  async function loadCompletedTranslations() {
    try {
      const histories = await window.aivicApi.list(translationHistoryIndex);
      if (histories) {
        const completedHistories = histories.filter(h => 
          h.翻訳ステータス === '完了' || h.translationStatus === 'completed'
        );
        renderRows(completedHistories);
      } else {
        // API未接続時は初期データを使用
        const completedRecords = (tables[translationHistoryIndex]?.records || []).filter(r => 
          r.翻訳ステータス === '完了' || r.translationStatus === 'completed'
        );
        renderRows(completedRecords);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderRows([]);
    }
  }

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const selectedLang = container.querySelector("#select-language").value;

    try {
      const histories = await window.aivicApi.list(translationHistoryIndex);
      if (histories) {
        let filtered = histories.filter(h => 
          (h.翻訳ステータス === '完了' || h.translationStatus === 'completed') &&
          (keyword === '' || (h.ファイル名 || h.fileName || '').toLowerCase().includes(keyword)) &&
          (selectedLang === '' || h.翻訳言語ペア === selectedLang)
        );
        renderRows(filtered);
      }
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 全選択チェックボックス
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".file-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // ダウンロード進捗表示
  function showProgress(percent) {
    progressDiv.classList.remove("hidden");
    progressBar.style.width = percent + "%";
    progressText.textContent = percent + "%";
  }

  function hideProgress() {
    progressDiv.classList.add("hidden");
  }

  // 個別ダウンロード
  async function downloadFile(fileId) {
    showProgress(0);

    // ダウンロード進捗をシミュレート
    for (let i = 0; i <= 100; i += 10) {
      showProgress(i);
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    // 実際のファイルダウンロード処理をシミュレート
    const format = container.querySelector("#select-format").value;
    const fileName = `translated_file_${fileId}.${format === 'original' ? 'pdf' : format}`;

    // ダミーファイル作成
    const content = `翻訳済みファイル\nファイルID: ${fileId}\n形式: ${format}\n\nこれは翻訳結果のサンプルです。`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    a.click();

    URL.revokeObjectURL(url);
    hideProgress();
  }

  // 一括ダウンロード
  container.querySelector("#btn-bulk-download").addEventListener("click", async () => {
    const checkedBoxes = container.querySelectorAll(".file-checkbox:checked");
    if (checkedBoxes.length === 0) {
      alert("ダウンロードするファイルを選択してください。");
      return;
    }

    showProgress(0);

    for (let i = 0; i < checkedBoxes.length; i++) {
      const progress = Math.floor((i + 1) / checkedBoxes.length * 100);
      showProgress(progress);
      await new Promise(resolve => setTimeout(resolve, 500));
    }

    // ZIPファイルとしてダウンロード（シミュレート）
    const zipContent = `一括ダウンロードファイル\n選択されたファイル数: ${checkedBoxes.length}`;
    const blob = new Blob([zipContent], { type: 'application/zip' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = 'translated_files.zip';
    a.click();

    URL.revokeObjectURL(url);
    hideProgress();
  });

  // プレビュー表示
  function showPreview(fileId) {
    const sampleContent = `翻訳結果プレビュー

ファイルID: ${fileId}

【原文】
This is a sample document for translation testing.
The system supports multiple file formats including PDF, Word, and Excel.

【翻訳文】
これは翻訳テスト用のサンプル文書です。
システムはPDF、Word、Excelを含む複数のファイル形式をサポートしています。

翻訳品質: 85点
翻訳エンジン: DeepL Pro
処理時間: 2分30秒`;

    previewContent.textContent = sampleContent;
    previewModal.classList.remove("hidden");
  }

  // プレビューモーダル閉じる
  container.querySelector("#close-preview").addEventListener("click", () => {
    previewModal.classList.add("hidden");
  });

  // モーダル背景クリックで閉じる
  previewModal.addEventListener("click", (e) => {
    if (e.target === previewModal) {
      previewModal.classList.add("hidden");
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const downloadBtn = e.target.closest(".download-btn");
    const previewBtn = e.target.closest(".preview-btn");
    const historyBtn = e.target.closest(".history-btn");

    if (downloadBtn) {
      const fileId = downloadBtn.dataset.id;
      await downloadFile(fileId);
    }

    if (previewBtn) {
      const fileId = previewBtn.dataset.id;
      showPreview(fileId);
    }

    if (historyBtn) {
      const fileId = historyBtn.dataset.id;
      window.showScreen("scr-1778473247810"); // 翻訳履歴詳細画面
    }
  });

  // 初期データ読み込み
  loadCompletedTranslations();
}

function(container, apiUrl, tables) {
  let translationInterval = null;
  let currentTranslation = null;

  // ファイル一覧を読み込み
  async function loadFiles() {
    const files = await window.aivicApi.list(1); // ファイルアップロード管理テーブル
    const fileSelect = container.querySelector('#select-file');
    fileSelect.innerHTML = '<option value="">ファイルを選択してください</option>';
    if (files) {
      files.forEach(file => {
        const option = document.createElement('option');
        option.value = file.id;
        option.textContent = file.ファイル名 || 'Unknown File';
        fileSelect.appendChild(option);
      });
    }
  }

  // 翻訳エンジン一覧を読み込み
  async function loadEngines() {
    const engines = await window.aivicApi.list(4); // 翻訳エンジン設定テーブル
    const engineRadios = container.querySelectorAll('input[name="engine"]');
    const engineContainer = engineRadios[0].closest('div');

    if (engines && engines.length > 0) {
      engineContainer.innerHTML = '';
      engines.filter(e => e.有効フラグ).forEach((engine, index) => {
        const label = document.createElement('label');
        label.style.display = 'block';
        label.style.marginBottom = '8px';
        label.innerHTML = `<input type="radio" name="engine" value="${engine.id}" ${index === 0 ? 'checked' : ''}> ${engine.エンジン名}`;
        engineContainer.appendChild(label);
      });
    }
  }

  // 品質スライダーの値更新
  const qualitySlider = container.querySelector('#quality-slider');
  const qualityValue = container.querySelector('#quality-value');
  qualitySlider.addEventListener('input', () => {
    qualityValue.textContent = qualitySlider.value;
  });

  // 翻訳開始ボタン
  container.querySelector('#btn-start').addEventListener('click', async () => {
    const fileId = container.querySelector('#select-file').value;
    const sourceLang = container.querySelector('#select-source-lang').value;
    const targetLang = container.querySelector('#select-target-lang').value;
    const engineId = container.querySelector('input[name="engine"]:checked').value;
    const qualityLevel = container.querySelector('#quality-slider').value;

    if (!fileId) {
      alert('翻訳対象ファイルを選択してください');
      return;
    }

    if (sourceLang === targetLang) {
      alert('原言語と翻訳先言語が同じです');
      return;
    }

    // 翻訳履歴を作成
    const translationData = {
      ファイルアップロードID: fileId,
      翻訳エンジンID: engineId,
      翻訳ステータス: '処理中',
      翻訳品質スコア: null,
      翻訳開始日時: new Date().toISOString()
    };

    currentTranslation = await window.aivicApi.save(5, translationData); // 翻訳履歴テーブル

    if (currentTranslation) {
      startTranslation();
    }
  });

  // 一時停止ボタン
  container.querySelector('#btn-pause').addEventListener('click', () => {
    if (translationInterval) {
      clearInterval(translationInterval);
      translationInterval = null;
      updateStatus('翻訳を一時停止しました');
      container.querySelector('#btn-start').disabled = false;
      container.querySelector('#btn-pause').disabled = true;
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', async () => {
    if (confirm('翻訳をキャンセルしますか？')) {
      if (translationInterval) {
        clearInterval(translationInterval);
        translationInterval = null;
      }

      if (currentTranslation) {
        await window.aivicApi.update(5, currentTranslation.id, { 翻訳ステータス: 'キャンセル' });
      }

      resetTranslation();
      updateStatus('翻訳をキャンセルしました');
    }
  });

  // 翻訳開始処理
  function startTranslation() {
    const totalSentences = Math.floor(Math.random() * 500) + 100; // シミュレーション用
    let processedSentences = 0;
    const startTime = Date.now();

    container.querySelector('#total-count').textContent = totalSentences;
    container.querySelector('#btn-start').disabled = true;
    container.querySelector('#btn-pause').disabled = false;
    container.querySelector('#btn-cancel').disabled = false;

    updateStatus('翻訳処理を開始しました');

    translationInterval = setInterval(() => {
      processedSentences += Math.floor(Math.random() * 5) + 1;

      if (processedSentences >= totalSentences) {
        processedSentences = totalSentences;
        completeTranslation();
        return;
      }

      updateProgress(processedSentences, totalSentences, startTime);
    }, 1000);
  }

  // 進捗更新
  function updateProgress(processed, total, startTime) {
    const progress = Math.floor((processed / total) * 100);
    const elapsed = Date.now() - startTime;
    const rate = processed / (elapsed / 1000);
    const remaining = Math.ceil((total - processed) / rate);

    container.querySelector('#processed-count').textContent = processed;
    container.querySelector('#progress-text').textContent = `${progress}%`;
    container.querySelector('#progress-bar').style.width = `${progress}%`;

    const minutes = Math.floor(remaining / 60);
    const seconds = remaining % 60;
    container.querySelector('#remaining-time').textContent = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;

    updateStatus(`翻訳処理中... (${processed}/${total} 文章)`);
  }

  // 翻訳完了
  async function completeTranslation() {
    clearInterval(translationInterval);
    translationInterval = null;

    const qualityScore = Math.floor(Math.random() * 30) + 70; // 70-100のランダムスコア

    if (currentTranslation) {
      await window.aivicApi.update(5, currentTranslation.id, {
        翻訳ステータス: '完了',
        翻訳品質スコア: qualityScore
      });
    }

    container.querySelector('#progress-text').textContent = '100%';
    container.querySelector('#progress-bar').style.width = '100%';
    container.querySelector('#remaining-time').textContent = '00:00';

    updateStatus(`翻訳が完了しました (品質スコア: ${qualityScore})`);

    resetTranslation();

    // 翻訳結果確認画面への遷移を提案
    setTimeout(() => {
      if (confirm('翻訳が完了しました。翻訳結果を確認しますか？')) {
        window.showScreen('scr-1778473719985');
      }
    }, 1000);
  }

  // 翻訳状態リセット
  function resetTranslation() {
    container.querySelector('#btn-start').disabled = false;
    container.querySelector('#btn-pause').disabled = true;
    container.querySelector('#btn-cancel').disabled = true;
    currentTranslation = null;
  }

  // ステータス更新
  function updateStatus(message) {
    const statusArea = container.querySelector('#status-area');
    const timestamp = new Date().toLocaleTimeString();
    statusArea.innerHTML = `<div style="color: var(--text);">${message}</div><div style="font-size: 12px; color: var(--text-muted); margin-top: 4px;">${timestamp}</div>`;
  }

  // 初期化
  loadFiles();
  loadEngines();
}

function(container, apiUrl, tables) {
