            <li>問題が継続する場合は管理者にお問い合わせください</li>
          </ul>
        </div>
      `;

      errorModal.classList.remove('hidden');
    }
  });
}

function(container, apiUrl, tables) {
  let translationTimer = null;
  let startTime = null;
  let currentTranslationId = null;

  // ファイル一覧を読み込み
  async function loadFiles() {
    const files = await window.aivicApi.list(1); // ファイルアップロード管理テーブル
    const fileSelect = container.querySelector('#select-file');
    fileSelect.innerHTML = '<option value="">ファイルを選択してください</option>';

    if (files) {
      files.forEach(file => {
        const option = document.createElement('option');
        option.value = file.id;
        option.textContent = file.ファイル名 || 'Unknown File';
        fileSelect.appendChild(option);
      });
    }
  }

  // 翻訳エンジン一覧を読み込み
  async function loadEngines() {
    const engines = await window.aivicApi.list(4); // 翻訳エンジン設定テーブル
    const engineContainer = container.querySelector('#engine-options');
    engineContainer.innerHTML = '';

    if (engines) {
      engines.filter(engine => engine.有効フラグ).forEach((engine, index) => {
        const label = document.createElement('label');
        label.style.cssText = 'display: flex; align-items: center; gap: 8px; color: var(--text);';
        label.innerHTML = `
          <input type="radio" name="translation-engine" value="${engine.id}" ${index === 0 ? 'checked' : ''} style="margin: 0;">
          ${engine.エンジン名 || 'Unknown Engine'}
        `;
        engineContainer.appendChild(label);
      });
    }
  }

  // 処理時間を更新
  function updateProcessingTime() {
    if (startTime) {
      const elapsed = Math.floor((Date.now() - startTime) / 1000);
      const hours = Math.floor(elapsed / 3600).toString().padStart(2, '0');
      const minutes = Math.floor((elapsed % 3600) / 60).toString().padStart(2, '0');
      const seconds = (elapsed % 60).toString().padStart(2, '0');
      container.querySelector('#processing-time').textContent = `${hours}:${minutes}:${seconds}`;
    }
  }

  // 進捗を更新
  function updateProgress(percentage, status) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const statusArea = container.querySelector('#status-area');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}%`;
    statusArea.textContent = status;
  }

  // 翻訳実行
  async function executeTranslation() {
    const fileId = container.querySelector('#select-file').value;
    const sourceLang = container.querySelector('#select-source-lang').value;
    const targetLang = container.querySelector('#select-target-lang').value;
    const engineRadio = container.querySelector('input[name="translation-engine"]:checked');
    const quality = container.querySelector('#select-quality').value;
    const useDictionary = container.querySelector('#check-dictionary').checked;

    if (!fileId || !sourceLang || !targetLang || !engineRadio) {
      alert('必要な項目を全て選択してください');
      return;
    }

    if (sourceLang === targetLang) {
      alert('原文言語と翻訳先言語は異なる言語を選択してください');
      return;
    }

    // 翻訳履歴を作成
    const translationData = {
      ファイルアップロードID: fileId,
      翻訳エンジンID: engineRadio.value,
      翻訳ステータス: '処理中',
      翻訳品質スコア: null,
      翻訳開始日時: new Date().toISOString()
    };

    const savedTranslation = await window.aivicApi.save(5, translationData); // 翻訳履歴テーブル
    if (!savedTranslation) return;

    currentTranslationId = savedTranslation.id;
    startTime = Date.now();

    // UI状態を更新
    container.querySelector('#btn-execute').disabled = true;
    container.querySelector('#btn-stop').disabled = false;
    updateProgress(0, '翻訳処理を開始しています...');

    // 翻訳進捗をシミュレート
    let progress = 0;
    translationTimer = setInterval(async () => {
      progress += Math.random() * 15 + 5; // 5-20%ずつ進捗
      if (progress > 100) progress = 100;

      let status = '翻訳処理中...';
      if (progress < 30) {
        status = 'ファイルを解析しています...';
      } else if (progress < 70) {
        status = 'テキストを翻訳しています...';
      } else if (progress < 95) {
        status = '翻訳結果を整形しています...';
      } else if (progress >= 100) {
        status = '翻訳が完了しました';
        clearInterval(translationTimer);

        // 翻訳完了処理
        await window.aivicApi.update(5, currentTranslationId, {
          翻訳ステータス: '完了',
          翻訳品質スコア: Math.floor(Math.random() * 20) + 80 // 80-99のスコア
        });

        container.querySelector('#btn-execute').disabled = false;
        container.querySelector('#btn-stop').disabled = true;

        // プレビューエリアに結果を表示
        const previewArea = container.querySelector('#preview-area');
        previewArea.innerHTML = `
          <div style="border-left: 3px solid #4a90e2; background: var(--bg-card); padding: 12px; margin-bottom: 10px;">
            <strong style="color: var(--text);">翻訳完了</strong>
            <div style="color: var(--text-muted); font-size: 14px; margin-top: 5px;">
              品質スコア: ${Math.floor(Math.random() * 20) + 80}/100
            </div>
          </div>
          <div style="color: var(--text);">
            <p><strong>原文例:</strong> これは翻訳のサンプルテキストです。</p>
            <p><strong>翻訳結果:</strong> This is a sample text for translation.</p>
            <hr style="border: none; border-top: 1px solid var(--border); margin: 15px 0;">
            <p style="color: var(--text-muted); font-size: 14px;">
              ※ 実際の翻訳結果は選択したファイルの内容によって異なります。
            </p>
          </div>
        `;
      }

      updateProgress(Math.floor(progress), status);
      updateProcessingTime();
    }, 1000);
  }

  // 翻訳停止
  async function stopTranslation() {
    if (translationTimer) {
      clearInterval(translationTimer);
      translationTimer = null;
    }

    if (currentTranslationId) {
      await window.aivicApi.update(5, currentTranslationId, {
        翻訳ステータス: 'キャンセル'
      });
    }

    container.querySelector('#btn-execute').disabled = false;
    container.querySelector('#btn-stop').disabled = true;
    updateProgress(0, '翻訳が停止されました');
    container.querySelector('#processing-time').textContent = '00:00:00';
    startTime = null;
    currentTranslationId = null;
  }

  // イベントリスナー
  container.querySelector('#btn-execute').addEventListener('click', executeTranslation);
  container.querySelector('#btn-stop').addEventListener('click', stopTranslation);

  // 初期データ読み込み
  loadFiles();
  loadEngines();
}

function(container, apiUrl, tables) {
  // 品質レベルの表示更新
  const qualitySlider = container.querySelector('#quality-level');
  const qualityValue = container.querySelector('#quality-value');
  const qualityLabels = ['高速', '高速', '標準', '高品質', '高品質'];

  qualitySlider.addEventListener('input', () => {
    qualityValue.textContent = qualityLabels[qualitySlider.value - 1];
  });

  // 翻訳エンジン一覧を読み込み
  async function loadEngines() {
    const engines = await window.aivicApi.list(4); // 翻訳エンジン設定テーブル
    const engineSelect = container.querySelector('#translation-engine');
    engineSelect.innerHTML = '<option value="">選択してください</option>';
    if (engines) {
      engines.filter(e => e.有効フラグ).forEach(engine => {
        engineSelect.innerHTML += `<option value="${engine.エンジンID}">${engine.エンジン名}</option>`;
      });
    }
  }

  // 設定テーブル再描画関数
  function renderSettings(settings) {
    const tbody = container.querySelector('#settings-tbody');
    tbody.innerHTML = settings.map(setting => `
      <tr data-id="${setting.設定ID}">
        <td>${setting.設定キー || ''}</td>
        <td>${setting.設定値 || ''}</td>
        <td>${setting.更新日時 ? new Date(setting.更新日時).toLocaleString() : ''}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${setting.設定ID}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${setting.設定ID}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadEngines();
    const settings = await window.aivicApi.list(6); // システム設定テーブル
    if (settings) {
      renderSettings(settings);
      // 既存設定をフォームに反映
      settings.forEach(setting => {
        const key = setting.設定キー;
        const value = setting.設定値;

        switch(key) {
          case 'translation_engine':
            container.querySelector('#translation-engine').value = value;
            break;
          case 'source_language':
            container.querySelector('#source-language').value = value;
            break;
          case 'target_language':
            container.querySelector('#target-language').value = value;
            break;
          case 'quality_level':
            container.querySelector('#quality-level').value = value;
            qualityValue.textContent = qualityLabels[value - 1];
            break;
          case 'dictionary':
            container.querySelector('#dictionary').value = value;
            break;
          case 'supported_formats':
            const formats = value.split(',');
            formats.forEach(format => {
              const checkbox = container.querySelector(`#format-${format}`);
              if (checkbox) checkbox.checked = true;
            });
            break;
          case 'speed_priority':
            const radio = container.querySelector(`input[name="speed-priority"][value="${value}"]`);
            if (radio) radio.checked = true;
            break;
          case 'use_translation_memory':
            container.querySelector('#use-translation-memory').checked = value === 'true';
            break;
          case 'character_limit':
            container.querySelector('#character-limit').value = value;
            break;
          case 'retention_days':
            container.querySelector('#retention-days').value = value;
            break;
          case 'auto_start':
            container.querySelector('#auto-start').checked = value === 'true';
            break;
          case 'completion_notification':
            container.querySelector('#completion-notification').checked = value === 'true';
            break;
        }
      });
    }
  }

  // 設定保存
  container.querySelector('#btn-save').addEventListener('click', async () => {
    const settings = [
      { key: 'translation_engine', value: container.querySelector('#translation-engine').value },
      { key: 'source_language', value: container.querySelector('#source-language').value },
      { key: 'target_language', value: container.querySelector('#target-language').value },
      { key: 'quality_level', value: container.querySelector('#quality-level').value },
      { key: 'dictionary', value: container.querySelector('#dictionary').value },
      { key: 'supported_formats', value: Array.from(container.querySelectorAll('input[type="checkbox"][id^="format-"]:checked')).map(cb => cb.value).join(',') },
      { key: 'speed_priority', value: container.querySelector('input[name="speed-priority"]:checked').value },
      { key: 'use_translation_memory', value: container.querySelector('#use-translation-memory').checked.toString() },
      { key: 'character_limit', value: container.querySelector('#character-limit').value },
      { key: 'retention_days', value: container.querySelector('#retention-days').value },
      { key: 'auto_start', value: container.querySelector('#auto-start').checked.toString() },
      { key: 'completion_notification', value: container.querySelector('#completion-notification').checked.toString() }
    ];

    for (const setting of settings) {
      if (setting.value) {
        const saved = await window.aivicApi.save(6, {
          設定キー: setting.key,
          設定値: setting.value,
          設定説明: `翻訳設定: ${setting.key}`,
          有効フラグ: true,
          更新日時: new Date().toISOString()
        });

        if (!saved) {
          alert('設定の保存に失敗しました');
          return;
        }
      }
    }

    alert('設定を保存しました');
    const updatedSettings = await window.aivicApi.list(6);
    if (updatedSettings) {
      renderSettings(updatedSettings);
    }
  });

  // 翻訳実行画面への遷移
  container.querySelector('#btn-execute').addEventListener('click', () => {
    window.showScreen("scr-1778473848118");
  });

  // 設定削除・編集のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この設定を削除しますか？')) return;
      await window.aivicApi.delete(6, deleteBtn.dataset.id);
      const settings = await window.aivicApi.list(6);
      if (settings) {
        renderSettings(settings);
      }
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const row = editBtn.closest('tr');
      const key = row.children[0].textContent;
      const currentValue = row.children[1].textContent;
      const newValue = prompt(`${key}の新しい値を入力してください:`, currentValue);

      if (newValue !== null && newValue !== currentValue) {
        const updated = await window.aivicApi.update(6, editBtn.dataset.id, {
          設定値: newValue,
          更新日時: new Date().toISOString()
        });

        if (updated) {
          const settings = await window.aivicApi.list(6);
          if (settings) {
            renderSettings(settings);
          }
        }
      }
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}

