function(container, apiUrl, tables) {
  // 翻訳履歴データから最新の完了した翻訳情報を取得
  function getLatestTranslation() {
    const translationHistory = tables[5]?.records || [];
    const fileUploads = tables[1]?.records || [];
    const translationEngines = tables[4]?.records || [];

    // 最新の完了した翻訳を取得
    const latestTranslation = translationHistory
      .filter(t => t.翻訳ステータス === '完了')
      .sort((a, b) => new Date(b.翻訳開始日時) - new Date(a.翻訳開始日時))[0];

    if (latestTranslation) {
      const file = fileUploads.find(f => f.ファイルID === latestTranslation.ファイルアップロードID);
      const engine = translationEngines.find(e => e.エンジンID === latestTranslation.翻訳エンジンID);

      return {
        translation: latestTranslation,
        file: file,
        engine: engine
      };
    }

    return null;
  }

  // 画面の初期表示データを設定
  function initializeDisplay() {
    const data = getLatestTranslation();

    if (data) {
      const fileName = container.querySelector('#file-name');
      const languagePair = container.querySelector('#language-pair');
      const processingTime = container.querySelector('#processing-time');
      const qualityScore = container.querySelector('#quality-score');
      const qualityBar = container.querySelector('#quality-bar');

      if (fileName && data.file) {
        fileName.textContent = data.file.ファイル名 || 'document.pdf';
      }

      if (languagePair) {
        languagePair.textContent = '日本語 → 英語'; // デフォルト値
      }

      if (processingTime && data.translation.翻訳開始日時) {
        const startTime = new Date(data.translation.翻訳開始日時);
        const endTime = new Date(); // 現在時刻を完了時刻として使用
        const diffMs = endTime - startTime;
        const minutes = Math.floor(diffMs / 60000);
        const seconds = Math.floor((diffMs % 60000) / 1000);
        processingTime.textContent = `${minutes}分${seconds}秒`;
      }

      if (qualityScore && data.translation.翻訳品質スコア) {
        const score = data.translation.翻訳品質スコア;
        qualityScore.textContent = score;
        if (qualityBar) {
          qualityBar.style.width = `${score}%`;
        }
      }
    }
  }

  // 翻訳詳細情報を表示
  function renderTranslationDetails() {
    const data = getLatestTranslation();
    const tbody = container.querySelector('#details-tbody');

    if (!tbody || !data) return;

    const details = [
      ['翻訳履歴ID', data.translation.翻訳履歴ID || ''],
      ['ファイル名', data.file?.ファイル名 || ''],
      ['翻訳エンジン', data.engine?.エンジン名 || ''],
      ['翻訳ステータス', data.translation.翻訳ステータス || ''],
      ['品質スコア', data.translation.翻訳品質スコア || ''],
      ['開始日時', data.translation.翻訳開始日時 || '']
    ];

    tbody.innerHTML = details.map(([key, value]) => 
      `<tr><td>${key}</td><td>${value}</td></tr>`
    ).join('');
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 翻訳結果ダウンロード
    const btnDownload = container.querySelector('#btn-download');
    if (btnDownload) {
      btnDownload.addEventListener('click', () => {
        const data = getLatestTranslation();
        if (data && data.file) {
          // 実際の実装では翻訳結果ファイルのダウンロード処理
          alert(`${data.file.ファイル名}の翻訳結果をダウンロードします`);
        }
      });
    }

    // 結果確認（翻訳結果確認画面へ遷移）
    const btnPreview = container.querySelector('#btn-preview');
    if (btnPreview) {
      btnPreview.addEventListener('click', () => {
        window.showScreen("scr-1778473719985");
      });
    }

    // 翻訳履歴
    const btnHistory = container.querySelector('#btn-history');
    if (btnHistory) {
      btnHistory.addEventListener('click', () => {
        const detailsDiv = container.querySelector('#translation-details');
        if (detailsDiv) {
          if (detailsDiv.classList.contains('hidden')) {
            detailsDiv.classList.remove('hidden');
            renderTranslationDetails();
            btnHistory.textContent = '📋 履歴を閉じる';
          } else {
            detailsDiv.classList.add('hidden');
            btnHistory.textContent = '📋 翻訳履歴';
          }
        }
      });
    }

    // 品質評価
    const btnEvaluate = container.querySelector('#btn-evaluate');
    if (btnEvaluate) {
      btnEvaluate.addEventListener('click', async () => {
        const data = getLatestTranslation();
        if (data) {
          const score = prompt('翻訳品質を1-5で評価してください（5が最高）:');
          const comment = prompt('評価コメント（任意）:');

          if (score && !isNaN(score) && score >= 1 && score <= 5) {
            const evaluation = {
              翻訳履歴ID: data.translation.翻訳履歴ID,
              評価者ID: 'current-user-id', // 実際の実装では現在のユーザーID
              品質スコア: parseInt(score),
              評価コメント: comment || '',
              評価日時: new Date().toISOString()
            };

            const saved = await window.aivicApi.save(8, evaluation);
            if (saved) {
              alert('評価を保存しました');
            }
          }
        }
      });
    }

    // 通知設定
    const btnSettings = container.querySelector('#btn-settings');
    if (btnSettings) {
      btnSettings.addEventListener('click', () => {
        alert('通知設定画面に遷移します');
      });
    }

    // 新しい翻訳開始
    const btnNewTranslation = container.querySelector('#btn-new-translation');
    if (btnNewTranslation) {
      btnNewTranslation.addEventListener('click', () => {
        alert('新しい翻訳画面に遷移します');
      });
    }

    // ホームに戻る
    const btnHome = container.querySelector('#btn-home');
    if (btnHome) {
      btnHome.addEventListener('click', () => {
        alert('ホーム画面に遷移します');
      });
    }
  }

  // 初期化処理
  initializeDisplay();
  setupEventListeners();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#tbody-files");
  let currentEvaluationId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => {
      const fileName = row.ファイル名 || row.fileName || "";
      const languagePair = row.翻訳言語ペア || row.languagePair || "ja-en";
      const completedDate = row.翻訳完了日時 || row.completedDate || new Date().toISOString();
      const fileSize = row.ファイルサイズ || row.fileSize || "0MB";
      const qualityScore = row.翻訳品質スコア || row.qualityScore || 0;

      const formatDate = (dateStr) => {
        try {
          return new Date(dateStr).toLocaleString('ja-JP');
        } catch {
          return dateStr;
        }
      };

      const formatLanguagePair = (pair) => {
        const pairs = {
          'ja-en': '日本語→英語',
          'en-ja': '英語→日本語',
          'ja-zh': '日本語→中国語',
          'zh-ja': '中国語→日本語',
          'ja-ko': '日本語→韓国語',
          'ko-ja': '韓国語→日本語'
        };
        return pairs[pair] || pair;
      };

      const getScoreBadge = (score) => {
        if (score >= 80) return `<span style="background: #28a745; color: #ffffff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${score}</span>`;
        if (score >= 60) return `<span style="background: #ffc107; color: #1a2a40; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${score}</span>`;
        return `<span style="background: #dc3545; color: #ffffff; padding: 2px 8px; border-radius: 12px; font-size: 12px;">${score}</span>`;
      };

      return `
        <tr data-id="${row.id || row.翻訳履歴ID || ''}">
          <td>${fileName}</td>
          <td>${formatLanguagePair(languagePair)}</td>
          <td>${formatDate(completedDate)}</td>
          <td>${fileSize}</td>
          <td>${getScoreBadge(qualityScore)}</td>
          <td>
            <button class="action-btn download-btn" data-id="${row.id || row.翻訳履歴ID || ''}" style="margin-right: 5px;">ダウンロード</button>
            <button class="action-btn secondary preview-btn" data-id="${row.id || row.翻訳履歴ID || ''}" style="margin-right: 5px;">プレビュー</button>
            <button class="action-btn secondary quality-btn" data-id="${row.id || row.翻訳履歴ID || ''}">品質評価</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadData() {
    const rows = await window.aivicApi.list(5); // 翻訳履歴テーブル
    if (rows) {
      // 翻訳完了のもののみフィルタ
      const completedRows = rows.filter(row => 
        (row.翻訳ステータス || row.translationStatus) === '完了'
      );
      renderRows(completedRows);
    } else {
      renderRows(tables[5]?.records || []);
    }
  }

  loadData();

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const languagePair = container.querySelector("#select-language-pair").value;
    const fileFormat = container.querySelector("#select-file-format").value;

    const rows = await window.aivicApi.list(5);
    if (rows) {
      let filteredRows = rows.filter(row => 
        (row.翻訳ステータス || row.translationStatus) === '完了'
      );

      if (keyword) {
        filteredRows = filteredRows.filter(row => 
          (row.ファイル名 || row.fileName || "").toLowerCase().includes(keyword)
        );
      }

      if (languagePair) {
        filteredRows = filteredRows.filter(row => 
          (row.翻訳言語ペア || row.languagePair) === languagePair
        );
      }

      if (fileFormat) {
        filteredRows = filteredRows.filter(row => {
          const fileName = row.ファイル名 || row.fileName || "";
          return fileName.toLowerCase().includes(`.${fileFormat}`);
        });
      }

      renderRows(filteredRows);
    }
  });

  // 4. CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(5);
    if (rows) {
      const completedRows = rows.filter(row => 
        (row.翻訳ステータス || row.translationStatus) === '完了'
      );

      const headers = ["ファイル名", "翻訳言語ペア", "翻訳完了日時", "ファイルサイズ", "品質スコア"];
      const csvContent = [
        headers.join(","),
        ...completedRows.map(row => [
          `"${row.ファイル名 || row.fileName || ""}"`,
          `"${row.翻訳言語ペア || row.languagePair || ""}"`,
          `"${row.翻訳完了日時 || row.completedDate || ""}"`,
          `"${row.ファイルサイズ || row.fileSize || ""}"`,
          `"${row.翻訳品質スコア || row.qualityScore || ""}"`
        ].join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "translation_downloads.csv";
      link.click();
    }
  });

  // 5. イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // ダウンロードボタン
    const downloadBtn = e.target.closest(".download-btn");
    if (downloadBtn) {
      const id = downloadBtn.dataset.id;
      // 実際のファイルダウンロード処理をシミュレート
      const link = document.createElement("a");
      link.href = `${apiUrl}/api/files/download/${id}`;
      link.download = `translated_file_${id}.pdf`;
      link.click();
      return;
    }

    // プレビューボタン
    const previewBtn = e.target.closest(".preview-btn");
    if (previewBtn) {
      const id = previewBtn.dataset.id;
      const modal = container.querySelector("#modal-preview");
      const title = container.querySelector("#preview-title");
      const content = container.querySelector("#preview-content");

      title.textContent = `ファイルプレビュー (ID: ${id})`;
      content.innerHTML = `
        <div style="text-align: center; color: var(--text-muted); padding: 40px;">
          <p>翻訳済みファイルのプレビューを表示中...</p>
          <p style="margin-top: 20px;">※ 実際の実装では、ファイル内容をここに表示します</p>
        </div>
      `;
      modal.classList.remove("hidden");
      return;
    }

    // 品質評価ボタン
    const qualityBtn = e.target.closest(".quality-btn");
    if (qualityBtn) {
      currentEvaluationId = qualityBtn.dataset.id;
      const modal = container.querySelector("#modal-quality");
      modal.classList.remove("hidden");
      return;
    }
  });

  // プレビューモーダル閉じる
  container.querySelector("#btn-close-preview").addEventListener("click", () => {
    container.querySelector("#modal-preview").classList.add("hidden");
  });

  // 品質評価モーダル閉じる
  container.querySelector("#btn-close-quality").addEventListener("click", () => {
    container.querySelector("#modal-quality").classList.add("hidden");
    currentEvaluationId = null;
  });

  container.querySelector("#btn-cancel-quality").addEventListener("click", () => {
    container.querySelector("#modal-quality").classList.add("hidden");
    currentEvaluationId = null;
  });

  // 品質評価保存
  container.querySelector("#btn-save-quality").addEventListener("click", async () => {
    if (!currentEvaluationId) return;

    const score = container.querySelector("#input-quality-score").value;
    const comment = container.querySelector("#input-quality-comment").value;

    const saved = await window.aivicApi.save(8, { // 翻訳品質評価テーブル
      翻訳履歴ID: currentEvaluationId,
      評価者ID: "current-user-id", // 実際の実装では現在のユーザーIDを使用
      品質スコア: parseInt(score),
      評価コメント: comment,
      評価日時: new Date().toISOString()
    });

    if (saved) {
      container.querySelector("#modal-quality").classList.add("hidden");
      container.querySelector("#input-quality-comment").value = "";
      currentEvaluationId = null;
      loadData(); // データを再読み込み
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#modal-preview").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) {
      container.querySelector("#modal-preview").classList.add("hidden");
    }
  });

  container.querySelector("#modal-quality").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) {
      container.querySelector("#modal-quality").classList.add("hidden");
      currentEvaluationId = null;
    }
  });
}

function(container, apiUrl, tables) {
  // 修正指示データを格納する仮想テーブル（実際のDBテーブルがないため）
  let instructionData = [
    {
      id: 'inst-001',
      translationHistoryId: 'hist-001',
      filename: 'contract_EN.pdf',
      originalText: 'This agreement shall be governed by the laws of Japan.',
      currentTranslation: 'この契約は日本の法律に支配される。',
      instruction: '「支配される」ではなく「準拠する」という表現に修正してください。法的文書としてより適切な表現です。',
      priority: '高',
      categories: ['専門用語', '文法・構文'],
      translatorId: 'user-002',
      translatorName: '田中翻訳者',
      deadline: '2024-01-20',
      status: '対応中',
      sentAt: '2024-01-15 10:30:00'
    }
  ];

  // 再描画関数の定義
  function renderInstructions(instructions) {
    const tbody = container.querySelector('#tbody-instructions');
    tbody.innerHTML = instructions.map(inst => `
      <tr data-id="${inst.id}">
        <td>${inst.sentAt}</td>
        <td>${inst.filename}</td>
        <td>${inst.translatorName}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; 
                       background: ${inst.priority === '高' ? '#dc3545' : inst.priority === '中' ? '#ffc107' : '#28a745'}; 
                       color: white;">
            ${inst.priority}
          </span>
        </td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis;">${inst.instruction}</td>
        <td>${inst.deadline}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 12px; font-size: 12px; 
                       background: ${inst.status === '完了' ? '#28a745' : inst.status === '対応中' ? '#007bff' : '#6c757d'}; 
                       color: white;">
            ${inst.status}
          </span>
        </td>
        <td>
          <button class="action-btn secondary view-btn" data-id="${inst.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${inst.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // 翻訳履歴データの読み込み
  async function loadTranslationHistories() {
    const histories = await window.aivicApi.list(5); // 翻訳履歴テーブル
    const select = container.querySelector('#select-translation-history');
    if (histories) {
      select.innerHTML = '<option value="">翻訳履歴を選択してください</option>' +
        histories.map(h => `<option value="${h.id}">${h.ファイルアップロードID || 'ファイル'} - ${h.翻訳開始日時 || '日時不明'}</option>`).join('');
    }
  }

  // 翻訳者データの読み込み
  async function loadTranslators() {
    const users = await window.aivicApi.list(0); // ユーザー管理テーブル
    const select = container.querySelector('#select-translator');
    if (users) {
      const translators = users.filter(u => u.権限レベル === 1 || u.権限レベル === 2);
      select.innerHTML = '<option value="">翻訳者を選択してください</option>' +
        translators.map(t => `<option value="${t.id}">${t.ユーザー名}</option>`).join('');
    }
  }

  // 初期データ読み込み
  loadTranslationHistories();
  loadTranslators();
  renderInstructions(instructionData);

  // 翻訳履歴選択時の処理
  container.querySelector('#select-translation-history').addEventListener('change', async function() {
    const historyId = this.value;
    if (!historyId) {
      container.querySelector('#label-filename').textContent = 'ファイルが選択されていません';
      container.querySelector('#textarea-original').value = '';
      container.querySelector('#textarea-current').value = '';
      return;
    }

    // 翻訳履歴から詳細情報を取得（実際の実装では API から取得）
    const histories = await window.aivicApi.list(5);
    const files = await window.aivicApi.list(1);

    if (histories && files) {
      const history = histories.find(h => h.id === historyId);
      const file = files.find(f => f.id === history?.ファイルアップロードID);

      if (file) {
        container.querySelector('#label-filename').textContent = file.ファイル名 || 'ファイル名不明';
      }

      // サンプルテキスト（実際の実装では翻訳データから取得）
      container.querySelector('#textarea-original').value = 'This agreement shall be governed by the laws of Japan and any disputes arising hereunder shall be subject to the exclusive jurisdiction of the Tokyo District Court.';
      container.querySelector('#textarea-current').value = 'この契約は日本の法律に支配され、これに基づいて生じる紛争は東京地方裁判所の専属管轄に服するものとします。';
    }
  });

  // 添付ファイル表示
  container.querySelector('#input-attachment').addEventListener('change', function() {
    const files = Array.from(this.files);
    const list = container.querySelector('#attachment-list');
    if (files.length > 0) {
      list.innerHTML = files.map(f => `<div>📎 ${f.name} (${Math.round(f.size/1024)}KB)</div>`).join('');
    } else {
      list.innerHTML = '';
    }
  });

  // 修正指示送信
  container.querySelector('#btn-send').addEventListener('click', function() {
    const historyId = container.querySelector('#select-translation-history').value;
    const instruction = container.querySelector('#textarea-instruction').value.trim();
    const priority = container.querySelector('input[name="priority"]:checked')?.value;
    const translatorId = container.querySelector('#select-translator').value;
    const deadline = container.querySelector('#input-deadline').value;

    if (!historyId || !instruction || !priority) {
      alert('必須項目を入力してください。');
      return;
    }

    const categories = [];
    if (container.querySelector('#check-terminology').checked) categories.push('専門用語');
    if (container.querySelector('#check-grammar').checked) categories.push('文法・構文');
    if (container.querySelector('#check-nuance').checked) categories.push('ニュアンス');
    if (container.querySelector('#check-format').checked) categories.push('書式・レイアウト');

    const newInstruction = {
      id: 'inst-' + Date.now(),
      translationHistoryId: historyId,
      filename: container.querySelector('#label-filename').textContent,
      originalText: container.querySelector('#textarea-original').value,
      currentTranslation: container.querySelector('#textarea-current').value,
      instruction: instruction,
      priority: priority,
      categories: categories,
      translatorId: translatorId,
      translatorName: container.querySelector('#select-translator option:checked').textContent,
      deadline: deadline,
      status: '送信済み',
      sentAt: new Date().toLocaleString('ja-JP', {year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit'}).replace(/\//g, '-')
    };

    instructionData.unshift(newInstruction);
    renderInstructions(instructionData);

    // フォームリセット
    container.querySelector('#select-translation-history').value = '';
    container.querySelector('#textarea-instruction').value = '';
    container.querySelector('#select-translator').value = '';
    container.querySelector('#input-deadline').value = '';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector('input[name="priority"][value="中"]').checked = true;
    container.querySelector('#input-attachment').value = '';
    container.querySelector('#attachment-list').innerHTML = '';
    container.querySelector('#label-filename').textContent = 'ファイルが選択されていません';
    container.querySelector('#textarea-original').value = '';
    container.querySelector('#textarea-current').value = '';

    alert('修正指示を送信しました。');
  });

  // 下書き保存
  container.querySelector('#btn-draft').addEventListener('click', function() {
    const instruction = container.querySelector('#textarea-instruction').value.trim();
    if (!instruction) {
      alert('修正指示内容を入力してください。');
      return;
    }

    // 実際の実装では下書きテーブルに保存
    alert('下書きを保存しました。');
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', function() {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const filtered = instructionData.filter(inst => 
      JSON.stringify(inst).toLowerCase().includes(keyword)
    );
    renderInstructions(filtered);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', function() {
    const headers = ['送信日時', 'ファイル名', '翻訳者', '優先度', '修正指示内容', '期限', 'ステータス'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      instructionData.map(inst => [
        inst.sentAt,
        `"${inst.filename}"`,
        `"${inst.translatorName}"`,
        inst.priority,
        `"${inst.instruction.replace(/"/g, '""')}"`,
        inst.deadline,
        inst.status
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '修正指示一覧_' + new Date().toISOString().slice(0,10) + '.csv';
    link.click();
  });

  // イベントデリゲーション（詳細・削除）
  container.addEventListener('click', function(e) {
    const viewBtn = e.target.closest('.view-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (viewBtn) {
      const id = viewBtn.dataset.id;
      const instruction = instructionData.find(inst => inst.id === id);
      if (instruction) {
        alert(`修正指示詳細:\n\n${instruction.instruction}\n\nカテゴリ: ${instruction.categories.join(', ')}\n期限: ${instruction.deadline}`);
      }
    }

    if (deleteBtn) {
      if (!confirm('この修正指示を削除しますか？')) return;
      const id = deleteBtn.dataset.id;
      const index = instructionData.findIndex(inst => inst.id === id);
      if (index !== -1) {
        instructionData.splice(index, 1);
        renderInstructions(instructionData);
        alert('修正指示を削除しました。');
      }
    }
  });
}
